package kun.cn.repository; import kun.cn.domain.ShopOrder; import org.springframework.data.jpa.repository.JpaRepository; import java.util.*; public interface OrderRepository extends JpaRepository<ShopOrder,Long>{ List<ShopOrder> findByCustomerNameOrderByCreatedAtDesc(String customerName); List<ShopOrder> findAllByOrderByCreatedAtDesc(); List<ShopOrder> findByOrderNoContainingIgnoreCaseOrderByCreatedAtDesc(String orderNo); }
